#include <iostream>
#include <string>
#include <markdown-cpp/markdown.h>

std::string markdownToHtml(const std::string& markdownText) {
    markdown::Markdown md;
    std::string htmlText = md.convert(markdownText);
    return htmlText;
}

int main() {
    std::string markdownText = "# Hello, World!\nThis is a markdown text";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "Markdown Text: " << markdownText << std::endl;
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

